#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cublas_v2.h>

void mixed_update_(torch::Tensor trailing, torch::Tensor panel) {
    TORCH_CHECK(trailing.is_cuda() && panel.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(trailing.scalar_type() == torch::kFloat32, "FP32 trailing matrix required");
    TORCH_CHECK(panel.scalar_type() == torch::kFloat16 ||
                panel.scalar_type() == torch::kFloat32,
                "FP16 or FP32 panel required");
    TORCH_CHECK(trailing.dim() == 3 && panel.dim() == 3, "batched matrices required");

    const int batch = static_cast<int>(panel.size(0));
    const int n = static_cast<int>(panel.size(1));
    const int k = static_cast<int>(panel.size(2));
    const int lda = static_cast<int>(panel.stride(1));
    const int ldc = static_cast<int>(trailing.stride(1));
    const int64_t panel_batch_stride = panel.stride(0);
    const int64_t trailing_batch_stride = trailing.stride(0);
    const float alpha = -1.0f;
    const float beta = 1.0f;

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    const bool use_fp16 = panel.scalar_type() == torch::kFloat16;
    const void* panel_ptr = use_fp16
        ? static_cast<const void*>(panel.data_ptr<at::Half>())
        : static_cast<const void*>(panel.data_ptr<float>());
    const cudaDataType panel_type = use_fp16 ? CUDA_R_16F : CUDA_R_32F;
    const cublasComputeType_t compute_type = use_fp16
        ? CUBLAS_COMPUTE_32F
        : CUBLAS_COMPUTE_32F_FAST_TF32;
    float* trailing_ptr = trailing.data_ptr<float>();
    // Row-major panel L is column-major L^T, while the symmetric row-major
    // output has the same column-major interpretation.  Explicit FP16 or
    // fast-TF32 compute selects Blackwell tensor cores for the rank-k update.
    const cublasStatus_t status = cublasGemmStridedBatchedEx(
        handle,
        CUBLAS_OP_T,
        CUBLAS_OP_N,
        n,
        n,
        k,
        &alpha,
        panel_ptr,
        panel_type,
        lda,
        panel_batch_stride,
        panel_ptr,
        panel_type,
        lda,
        panel_batch_stride,
        &beta,
        trailing_ptr,
        CUDA_R_32F,
        ldc,
        trailing_batch_stride,
        batch,
        compute_type,
        CUBLAS_GEMM_DEFAULT);
    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasGemmStridedBatchedEx failed");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mixed_update_", &mixed_update_, "In-place mixed-precision rank-k update");
}
